INSERT INTO reviews (user_id, clinic_id, doctor_id, provider, provider_review_id, rating, original_language, original_text, text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr, likes_count, published_at) VALUES
(@user_zorica_pavicevic, @clinic_id, @doctor_aleksandra_celebic, 'google_maps',
    'places/ChIJf4tB9nvrTRMRPE_1iP76aB8/reviews/Ci9DQUlRQUNvZENodHljRjlvT205YUxYWXdkVXhwT1ZvNVJtOXlOVjk1VW0xWU5WRRAB',
    5, 'hr', 'Postovana  Dr Aleksandra  zahvaljujem vam se,svako dobro zelim vama i vasim sestrama.',
    'Postovana  Dr Aleksandra  zahvaljujem vam se,svako dobro zelim vama i vasim sestrama.', NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-08 00:00:00'),

(@user_boban_djordjevic, @clinic_id, NULL, 'google_maps',
    'places/ChIJf4tB9nvrTRMRPE_1iP76aB8/reviews/Ci9DQUlRQUNvZENodHljRjlvT2psNVR6RTJaRVZpZDE4dFpFUXhOblpWYTNRelJrRRAB',
    5, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-08 00:00:00'),

(@user_dejana_rai, @clinic_id, NULL, 'google_maps',
    'places/ChIJf4tB9nvrTRMRPE_1iP76aB8/reviews/Ci9DQUlRQUNvZENodHljRjlvT210WE0zUkpZWEE1VHkxcmNtNUNlWGhuVjI5bVgyYxAB',
    5, 'bs', 'Želim od srca da se zahvalim cijelom
timu klinike na izuzetnoj brizi i profesionalnosti tokom mog lečenja i operacije.

Posebnu zahvalnost upućujem najdivnijoj doktorki, čija su stručnost, posvećenost, strpljenje i ljudskost učinili da se u svakom trenutku osećam sigurno i zbrinuto. Njena pažnja, razumevanje i požrtvovanost ostavili su na mene neizbrisiv utisak.

Veliko hvala i svim medicinskim sestrama koje su bile neverovatno ljubazne, brižne i uvek spremne da pomognu. Njihov osmijeh, podrška i toplina značili su mi mnogo u trenucima kada mi je to bilo najpotrebnije.

Rijetko se sreće tim koji svoj posao obavlja sa toliko ljubavi, empatije i profesionalizma. Hvala  vam na svu što ste ucinili za mene. Od srca vam želim puno uspeha u daljem radu i preporučujem ovu kliniku svima koji traže vrhunsku medicinsku negu i pre svega – ljudski pristup.',
    'Želim od srca da se zahvalim cijelom
timu klinike na izuzetnoj brizi i profesionalnosti tokom mog lečenja i operacije.

Posebnu zahvalnost upućujem najdivnijoj doktorki, čija su stručnost, posvećenost, strpljenje i ljudskost učinili da se u svakom trenutku osećam sigurno i zbrinuto. Njena pažnja, razumevanje i požrtvovanost ostavili su na mene neizbrisiv utisak.

Veliko hvala i svim medicinskim sestrama koje su bile neverovatno ljubazne, brižne i uvek spremne da pomognu. Njihov osmijeh, podrška i toplina značili su mi mnogo u trenucima kada mi je to bilo najpotrebnije.

Rijetko se sreće tim koji svoj posao obavlja sa toliko ljubavi, empatije i profesionalizma. Hvala  vam na svu što ste ucinili za mene. Od srca vam želim puno uspeha u daljem radu i preporučujem ovu kliniku svima koji traže vrhunsku medicinsku negu i pre svega – ljudski pristup.', NULL, NULL, NULL, NULL, NULL,
