(@user_nikolina_dragic, @clinic_id, NULL, 'google_maps',
    'places/ChIJYYi1_d_VTRMR5tohdKO0jQY/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pZMFZEQk9VMnQ0Y2tWbWNFaERMVkZyUm1WVFQxRRAB',
