(@user_ziza_krstovic, @clinic_id, @doctor_berin, 'google_maps',
    'places/ChIJd4vJErFzThMRE1QbgSVdvyY/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tsRmFXYzNUWEphVVV4WlVFa3ljbXhhVEY5YWFXYxAB',
    5, 'bs', 'Sve pohvale za doktora Berina, kao i za cijeli tim!Imala sam komplikovano hirursko vadjenje umnjaka, koje je proslo u najboljem redu.Hvala na profesionalnosti, ljubaznosti i brizi tokom cijelog procesa.Sve preporuke!',
    'Sve pohvale za doktora Berina, kao i za cijeli tim!Imala sam komplikovano hirursko vadjenje umnjaka, koje je proslo u najboljem redu.Hvala na profesionalnosti, ljubaznosti i brizi tokom cijelog procesa.Sve preporuke!', NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_kathryn_mcmanus, @clinic_id, NULL, 'google_maps',
