INSERT INTO reviews (user_id, clinic_id, doctor_id, provider, provider_review_id, rating, original_language, original_text, text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr, likes_count, published_at) VALUES
(@user_marija_beki, @clinic_id, NULL, 'google_maps',
    'places/ChIJh9GNyhXrTRMRpAcKDQoHEyk/reviews/Ci9DQUlRQUNvZENodHljRjlvT2t0WmJXeHRYMlU1VVRWT1ozUkxTa2h6WjJockxYYxAB',
    1, 'bs', 'Nestručno, neprofesionalno, dobila sam pogrešnu dijagnozu a ono što je trebalo biti dijagnostifikovano - nije. Gomila šarlatana koji mrvu svesti nemaju da rade s ljudskim životima. Zaobiđite ovu bagru u širokom luku ako imate druge opcije.',
    'Nestručno, neprofesionalno, dobila sam pogrešnu dijagnozu a ono što je trebalo biti dijagnostifikovano - nije. Gomila šarlatana koji mrvu svesti nemaju da rade s ljudskim životima. Zaobiđite ovu bagru u širokom luku ako imate druge opcije.', NULL, NULL, NULL, NULL, NULL,
    0, NULL),

(@user_elvisa_softic, @clinic_id, NULL, 'google_maps',
    'places/ChIJh9GNyhXrTRMRpAcKDQoHEyk/reviews/Ci9DQUlRQUNvZENodHljRjlvT205VWRYWlpYMWxQWkhWcVgwUm1ja1pSV1RoU1dVRRAB',
    1, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_filip_barabas, @clinic_id, NULL, 'google_maps',
    'places/ChIJh9GNyhXrTRMRpAcKDQoHEyk/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xSRFpqbG1VblF0UTI5V2RGcHRZV3Q0WTE5UGNXYxAB',
    1, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_radmila_rada_damjanovic_topalovic, @clinic_id, NULL, 'google_maps',
    'places/ChIJh9GNyhXrTRMRpAcKDQoHEyk/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pkU1oxTnJhVVl6WmpWd2F6Wk9OQzEwUzFCQ2JGRRAB',
    5, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_ivana_vujosevic, @clinic_id, NULL, 'google_maps',
    'places/ChIJh9GNyhXrTRMRpAcKDQoHEyk/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xCRlRqSnlhVWs1YjFvelVFbFZha1ZPT1RGSFZWRRAB',
    1, 'bs', 'Moje iskustvo sa Codra bolnicom, kada su u pitanju organizacija zakazivanja i odnos osoblja prema pacijentima, veoma je loše. Pacijentkinje se zakazuju u isti termin, po 10 žena odjednom. Kada unaprijed zamolite da vas stave na spisak za sljedeći dolazak doktora, to se ne ispoštuje. Ako pozovete pet dana ranije, kažu da je prerano, a kada pozovete na dan koji vam oni odrede, termini su već popunjeni. Na kraju vam zakažu termin sa još desetak žena. Uz sve to, sestre su veoma neljubazne i bez dovoljno razumijevanja za pacijente.

Jedina svijetla tačka ove bolnice je doktor Luka Anđelić, prema kojem imam posebnu ljubav, poštovanje i neizmjernu zahvalnost.  Za njega sve pohvale i hvala od srca!

Velika je šteta što tako divan doktor radi u sistemu u kojem su organizacija i odnos prema pacijentima na ovako niskom nivou. Za doktora Luku ocjena 10, a za organizaciju i ostalo osoblje — ocjena 0!',
