INSERT INTO reviews (user_id, clinic_id, doctor_id, provider, provider_review_id, rating, original_language, original_text, text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr, likes_count, published_at) VALUES
(@user_edo_jaki, @clinic_id, NULL, 'google_maps',
    'places/ChIJAXASNQB0ThMRjwGUJIrheG0/reviews/Ci9DQUlRQUNvZENodHljRjlvT2twRlkxbFdhWGg1UTJoRGRWUTFibmRQUlRsbVIwRRAB',
    5, 'bs', 'Sve pohvale na osobolje i samu doktoricu,nažalost došli smo iscrpljeni od virusa ,a sa njihove strane je sve bilo za pohvalu i profesionalno,pogotovo sestra koja nas je stavila
na infuzuju i dala nam inekcije,nismo imali zdravstveno osiguranje pa smo platili pregled i terapiju ukupno 62€ za dvoje ,čak nam je sestra izašla u susret pošto smo oboje imali iste simtome, pa da prodjemo jeftinije jer bi bilo 34€ po osobi samo pregled što je veliki plus i za pohvalu od sestre...',
    'Sve pohvale na osobolje i samu doktoricu,nažalost došli smo iscrpljeni od virusa ,a sa njihove strane je sve bilo za pohvalu i profesionalno,pogotovo sestra koja nas je stavila
na infuzuju i dala nam inekcije,nismo imali zdravstveno osiguranje pa smo platili pregled i terapiju ukupno 62€ za dvoje ,čak nam je sestra izašla u susret pošto smo oboje imali iste simtome, pa da prodjemo jeftinije jer bi bilo 34€ po osobi samo pregled što je veliki plus i za pohvalu od sestre...', NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

(@user_luka_abarkapa, @clinic_id, NULL, 'google_maps',
    'places/ChIJAXASNQB0ThMRjwGUJIrheG0/reviews/Ci9DQUlRQUNvZENodHljRjlvT21oVGEzcHlkVXR5WTBoRFFuVTFPV0ZuTjBGS05VRRAB',
    5, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

(@user_vlasta_gnjatovic, @clinic_id, NULL, 'google_maps',
    'places/ChIJAXASNQB0ThMRjwGUJIrheG0/reviews/Ci9DQUlRQUNvZENodHljRjlvT2paVFlWZHRXRFp3WDNka01YVnBhR051VWxCelNHYxAB',
