(@user_mirnes, @clinic_id, NULL, 'google_maps',
    'places/ChIJU1hzipzUTRMRin8KkYi4n7Q/reviews/Ci9DQUlRQUNvZENodHljRjlvT21KV1dVNW5TV2hRT0hSQlZsbzNNREJYZFcxNE4wRRAB',
