(@user_jim_xanthos, @clinic_id, NULL, 'google_maps',
    'places/ChIJD92qzinrTRMRoeZ77e_UMww/reviews/Ci9DQUlRQUNvZENodHljRjlvT21vdGMzQXlTSGR3TkRkTWFscDVOM1U0TVZOdUxYYxAB',
