    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_bojana_scekic, @clinic_id, @doctor_ivana_pejovic, 'google_maps',
    'places/ChIJD92qzinrTRMRoeZ77e_UMww/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xObGIxbERkMjF5UTFSWFRYZHJlV3N6U2xaVGRuYxAB',
    5, 'hr', 'Takav profesionalizam,ljubaznost i kvalitet danas se rijetko moze sresti. Radila sam usluge popunjavanja usana kod Dr. Ivane vise puta,i bila prezadovoljna. Provjereni materijali,sterilnost i higijena na najvisem mogucem nivou. Dr. Ivana svojim iskustvom napravila je remek djelo na mojim usnama,i ona je Pikaso sa iglom u ruci. Svaka preporuka !',
    'Takav profesionalizam,ljubaznost i kvalitet danas se rijetko moze sresti. Radila sam usluge popunjavanja usana kod Dr. Ivane vise puta,i bila prezadovoljna. Provjereni materijali,sterilnost i higijena na najvisem mogucem nivou. Dr. Ivana svojim iskustvom napravila je remek djelo na mojim usnama,i ona je Pikaso sa iglom u ruci. Svaka preporuka !', NULL, NULL, NULL, NULL, NULL,
