INSERT INTO reviews (user_id, clinic_id, doctor_id, provider, provider_review_id, rating, original_language, original_text, text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr, likes_count, published_at) VALUES
(@user_bilja_jaukovic, @clinic_id, NULL, 'google_maps',
    'places/ChIJOX8c_qqpTRMRy2AROS5r5wA/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xjeVFXTmZSelJoYTNrNFdFNXFiWEJ6ZDFsTFVGRRAB',
    5, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

(@user_petar_stijovi, @clinic_id, @doctor_stevan_kulusic, 'google_maps',
    'places/ChIJOX8c_qqpTRMRy2AROS5r5wA/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xONGMxOWZjak5SYVVrMFJFTkNlRlpHUXpadmFVRRAB',
    5, 'hr', 'Po preporuci sam došao na ugradnju implantata u ordinaciju Kulušić i moram priznati da sam prezadovoljan. Doktor Stevan je izuzetan stručnjak i čovek — izuzetno je profesionalan, posvećen i zaista brine o svom pacijentu. Još jednom, veliko hvala!',
    'Po preporuci sam došao na ugradnju implantata u ordinaciju Kulušić i moram priznati da sam prezadovoljan. Doktor Stevan je izuzetan stručnjak i čovek — izuzetno je profesionalan, posvećen i zaista brine o svom pacijentu. Još jednom, veliko hvala!', NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

(@user_kosa_drincic, @clinic_id, NULL, 'google_maps',
    'places/ChIJOX8c_qqpTRMRy2AROS5r5wA/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xVdE1IQjNkRWRMVWtORlVISXdRamhQU2pGWWIzYxAB',
    5, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

(@user_slavica_mitri, @clinic_id, NULL, 'google_maps',
    'places/ChIJOX8c_qqpTRMRy2AROS5r5wA/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xCSU1VcG9XVVV3VWtneFQwdFVaVlF3YUdGeWJIYxAB',
    5, 'hr', 'Taj dan kada sam ušla u ovu ordinaciju pamtit ću zauvijek. Ušla sam sa ogromnim bolom, ali još većim strahom — onim koji te stegne u grudima i ne pušta, kao da ti oduzme i dah i snagu u isto vrijeme. Sve u meni je bilo uplašeno i nesigurno, od pogleda do misli, i iskreno, samo sam željela da bol nestane...

A onda se desilo nešto što nisam očekivala. Umjesto nelagode i hladnoće, dočekali su me smirenost, toplina i osmijesi koji ulivaju povjerenje. Riječi koje su polako počele da brišu strah, bez žurbe, bez pritiska — samo razumijevanje i ljudskost. Korak po korak, pregled po pregled, bol i nervoza su se počeli topiti. Nisam ni primijetila kada je nestao onaj osjećaj panike koji sam nosila sa sobom. Ostala je samo sigurnost — da sam na pravom mjestu.

Danas znam da ovo nije bila samo estetska promjena — jer kad vratiš osmijeh, vratiš i dio sebe koji si mislio da si izgubio zauvijek. A upravo to se desilo meni. Nakon dugo vremena, ponovo se smijem iskreno, bez skrivanja, bez straha kako izgledam dok se smijem, bez potrebe da se sakrijem iza ruke ili pogleda.

Najljepši osjećaj nije samo kada se ponovo nasmiješ — nego kada shvatiš da to radiš bez razmišljanja. Kada u ogledalu više ne tražiš nesigurnost, nego prepoznaješ sebe onakvu kakva si nekada bila — mirniju, slobodniju, sretniju.

Hvala dragom doktoru Stevanu i divnoj doktorici Zorki i cijelom timu na strpljenju, pažnji, toplini i ljubavi prema poslu koju osjećate u svakom trenutku. Vi ne pravite samo lijepe osmijehe — vi ljudima vraćate sreću, sigurnost i vjeru u sebe.

Zauvijek ću biti zahvalna za osmijeh koji danas nosim sa ponosom… i za mir koji ste mi vratili zajedno s njim. 🤍🦷✨',
    'Taj dan kada sam ušla u ovu ordinaciju pamtit ću zauvijek. Ušla sam sa ogromnim bolom, ali još većim strahom — onim koji te stegne u grudima i ne pušta, kao da ti oduzme i dah i snagu u isto vrijeme. Sve u meni je bilo uplašeno i nesigurno, od pogleda do misli, i iskreno, samo sam željela da bol nestane...

A onda se desilo nešto što nisam očekivala. Umjesto nelagode i hladnoće, dočekali su me smirenost, toplina i osmijesi koji ulivaju povjerenje. Riječi koje su polako počele da brišu strah, bez žurbe, bez pritiska — samo razumijevanje i ljudskost. Korak po korak, pregled po pregled, bol i nervoza su se počeli topiti. Nisam ni primijetila kada je nestao onaj osjećaj panike koji sam nosila sa sobom. Ostala je samo sigurnost — da sam na pravom mjestu.

Danas znam da ovo nije bila samo estetska promjena — jer kad vratiš osmijeh, vratiš i dio sebe koji si mislio da si izgubio zauvijek. A upravo to se desilo meni. Nakon dugo vremena, ponovo se smijem iskreno, bez skrivanja, bez straha kako izgledam dok se smijem, bez potrebe da se sakrijem iza ruke ili pogleda.

Najljepši osjećaj nije samo kada se ponovo nasmiješ — nego kada shvatiš da to radiš bez razmišljanja. Kada u ogledalu više ne tražiš nesigurnost, nego prepoznaješ sebe onakvu kakva si nekada bila — mirniju, slobodniju, sretniju.

Hvala dragom doktoru Stevanu i divnoj doktorici Zorki i cijelom timu na strpljenju, pažnji, toplini i ljubavi prema poslu koju osjećate u svakom trenutku. Vi ne pravite samo lijepe osmijehe — vi ljudima vraćate sreću, sigurnost i vjeru u sebe.

Zauvijek ću biti zahvalna za osmijeh koji danas nosim sa ponosom… i za mir koji ste mi vratili zajedno s njim. 🤍🦷✨', NULL, NULL, NULL, NULL, NULL,
    0, '2026-07-29 00:00:00'),

(@user_kapor_branislav, @clinic_id, NULL, 'google_maps',
    'places/ChIJOX8c_qqpTRMRy2AROS5r5wA/reviews/Ci9DQUlRQUNvZENodHljRjlvT21SRmRuVk1USEF0VVdkYVNXbGFhMkozVDNaclVHYxAB',
    5, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-06-29 00:00:00'),

(@user_milica_bozovic, @clinic_id, NULL, 'google_maps',
    'places/ChIJOX8c_qqpTRMRy2AROS5r5wA/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tsYVpubG9VMGc0VDE5c1dXa3libXBOY1RGeWFHYxAB',
    2, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-05-29 00:00:00'),

(@user_natasa_radman_bovan, @clinic_id, NULL, 'google_maps',
    'places/ChIJOX8c_qqpTRMRy2AROS5r5wA/reviews/Ci9DQUlRQUNvZENodHljRjlvT2pFMVRuWkNRV1UxVUVSTVJISmtWR1JpVTNoU1VFRRAB',
    5, 'bs', 'Veoma sam zadovoljna iskustvom u ovoj ordinaciji. Od prvog dolaska stekli su moje potpuno povjerenje zahvaljujući svojoj stručnosti, posvećenosti i ljubaznosti.

Posebnu zahvalnost dugujem dr Zorki i dr Stevanu, kao i cijelom timu, a naročito medicinskoj sestri Milijani na pažnji i predusretljivosti.

Topla preporuka svima koji traže kvalitetnu i pouzdanu stomatološku uslugu.',
    'Veoma sam zadovoljna iskustvom u ovoj ordinaciji. Od prvog dolaska stekli su moje potpuno povjerenje zahvaljujući svojoj stručnosti, posvećenosti i ljubaznosti.

Posebnu zahvalnost dugujem dr Zorki i dr Stevanu, kao i cijelom timu, a naročito medicinskoj sestri Milijani na pažnji i predusretljivosti.

Topla preporuka svima koji traže kvalitetnu i pouzdanu stomatološku uslugu.', NULL, NULL, NULL, NULL, NULL,
    0, '2026-05-29 00:00:00')
