INSERT INTO reviews (user_id, clinic_id, doctor_id, provider, provider_review_id, rating, original_language, original_text, text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr, likes_count, published_at) VALUES
(@user_s_b, @clinic_id, NULL, 'google_maps',
    'places/ChIJd4Xss53UTRMRf1Aaa8EgS_Y/reviews/Ci9DQUlRQUNvZENodHljRjlvT2kxa05rRkJjV2cxTFVNeWJIQk9UMFo2UmxKWk1VRRAB',
    5, 'ru', 'С огромной благодарностью доктору Лидии пишу этот отзыв. У меня воспалился глаз, обратилась в страховую компанию, меня направили в центр LaserFocus. Со мной связалась доктор Lidija и назначила приём. Она провела подробный осмотр, включая проверку глазного давления, выписала лекарства, которые действительно помогли. Уже в первый же день мне стало легче, боль прошла, я следовала её рекомендациям и выполнила весь пятидневный курс лечения, после чего всё снова стало как должно быть — глаза в порядке! И ещё хочу отдельно отметить доктора Лидию — её профессионализм и внимание ко мне как пациенту, а также её доброжелательность и заботу. Спасибо такому замечательному врачу!',
    NULL, NULL, NULL, 'С огромной благодарностью доктору Лидии пишу этот отзыв. У меня воспалился глаз, обратилась в страховую компанию, меня направили в центр LaserFocus. Со мной связалась доктор Lidija и назначила приём. Она провела подробный осмотр, включая проверку глазного давления, выписала лекарства, которые действительно помогли. Уже в первый же день мне стало легче, боль прошла, я следовала её рекомендациям и выполнила весь пятидневный курс лечения, после чего всё снова стало как должно быть — глаза в порядке! И ещё хочу отдельно отметить доктора Лидию — её профессионализм и внимание ко мне как пациенту, а также её доброжелательность и заботу. Спасибо такому замечательному врачу!', NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_dan_james, @clinic_id, NULL, 'google_maps',
    'places/ChIJd4Xss53UTRMRf1Aaa8EgS_Y/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xObU9ISmxVbkJMTlU4dExWaFNaSFJzUzJSNVdGRRAB',
    5, 'en', 'Went to sort out my sinus infection and the dr was amazing she recommended me the exact medication I needed and she was very helpful, highly recommend',
