INSERT INTO reviews (user_id, clinic_id, doctor_id, provider, provider_review_id, rating, original_language, original_text, text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr, likes_count, published_at) VALUES
(@user_milena_radevi, @clinic_id, NULL, 'google_maps',
    'places/ChIJP0QWP1HrTRMRWfYKnPWtkaY/reviews/Ci9DQUlRQUNvZENodHljRjlvT2t4d1EySnpYM2xIVW04d2MyVnhkVVZtVm5jMmNGRRAB',
    5, 'hr', 'Na fizikalnu terapiju u Fizikalmed sam došla zbog jakih bolova u donjem dijelu leđa, zbog kojih nijesam mogla ni da spavam. Nakon 10 tretmana osjećam se mnogo bolje. Posebno mi znači što se terapija sve vrijeme prati i prilagođava mom stanju, pa sam imala osjećaj da je zaista napravljena za mene. Jako sam zadovoljna, sve preporuke!',
    'Na fizikalnu terapiju u Fizikalmed sam došla zbog jakih bolova u donjem dijelu leđa, zbog kojih nijesam mogla ni da spavam. Nakon 10 tretmana osjećam se mnogo bolje. Posebno mi znači što se terapija sve vrijeme prati i prilagođava mom stanju, pa sam imala osjećaj da je zaista napravljena za mene. Jako sam zadovoljna, sve preporuke!', NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-29 00:00:00'),

(@user_aleksandar_vukajlovic, @clinic_id, @doctor_aleksandar_vidic, 'google_maps',
    'places/ChIJP0QWP1HrTRMRWfYKnPWtkaY/reviews/Ci9DQUlRQUNvZENodHljRjlvT2taYVpITm1lR05TV0RWVU0wcGtaSFpwZVhGQlIxRRAB',
    5, 'bs', 'Imao sam problem sa donjim dijelom ledja, svakodnevni bol koji je iz dana u dan bio nepodnosljiv, dolaskom kod veoma strucnog i ljubaznog gospodina Aleksandra koji mi je bas pomogao, sad se odlicno osjecam i zajedno pratimo moje stanje ledja, sve preporuke !!',
    'Imao sam problem sa donjim dijelom ledja, svakodnevni bol koji je iz dana u dan bio nepodnosljiv, dolaskom kod veoma strucnog i ljubaznog gospodina Aleksandra koji mi je bas pomogao, sad se odlicno osjecam i zajedno pratimo moje stanje ledja, sve preporuke !!', NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_gordana_djurisic, @clinic_id, NULL, 'google_maps',
    'places/ChIJP0QWP1HrTRMRWfYKnPWtkaY/reviews/Ci9DQUlRQUNvZENodHljRjlvT25ZNVYzVkxiV1pKV1hKU2VXcGZhazV0TjJndFkwRRAB',
    5, 'hr', 'Sve pohvale!! Ljubaznost i stručnost na jednom mjestu!',
    'Sve pohvale!! Ljubaznost i stručnost na jednom mjestu!', NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-22 00:00:00'),

(@user_krsto_popovic, @clinic_id, @doctor_aleksandar_vidic, 'google_maps',
    'places/ChIJP0QWP1HrTRMRWfYKnPWtkaY/reviews/Ci9DQUlRQUNvZENodHljRjlvT2s5TE4zUndVR3d3Y1hrelRXdEVTMFpzUldGUlQzYxAB',
    5, 'hr', 'Imao sam problema sa tetivom na nozi jaki bolovi pri bilo kakvom  kretanju i jake grčeve u mišiću otisa sam kod Aleksandra i počeo sa terapijom posle odrađenih nekoliko terapija bilo je već malo bolje odradili smo 15 tertmana ja sam se oporavio bolovi su nestali i grčeva vise nemam sad sam počeo i da radim  i vratio se normalnim aktivnostima. Svaka preporuka za ordinaciju fizikalmed!',
    'Imao sam problema sa tetivom na nozi jaki bolovi pri bilo kakvom  kretanju i jake grčeve u mišiću otisa sam kod Aleksandra i počeo sa terapijom posle odrađenih nekoliko terapija bilo je već malo bolje odradili smo 15 tertmana ja sam se oporavio bolovi su nestali i grčeva vise nemam sad sam počeo i da radim  i vratio se normalnim aktivnostima. Svaka preporuka za ordinaciju fizikalmed!', NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-08 00:00:00'),

(@user_milan_rosandic, @clinic_id, NULL, 'google_maps',
    'places/ChIJP0QWP1HrTRMRWfYKnPWtkaY/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xWcmIxVTBUbk5MU0V4MGRWTmpSMk0yV1ZGblpuYxAB',
