INSERT INTO reviews (user_id, clinic_id, doctor_id, provider, provider_review_id, rating, original_language, original_text, text_sr, text_sr_cyrl, text_en, text_ru, text_de, text_tr, likes_count, published_at) VALUES
(@user_ece_k, @clinic_id, NULL, 'google_maps',
    'places/ChIJM8Gt42Q2TBMRvLuBwVtNCEQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT25kRWJVcERXbTVxWTJkSGNqUjBWSEZGY0Zsa1lWRRAB',
    1, 'en', 'I twisted both my ankles, was terrified they would be broken. We were referred from Budva Health Center, the lady at the reception was AWFUL. She wasn’t wearing a name badge but it happened 06/10/26 night shift (about 10-11 pm). I want her to be warned quite firmly about respect, communication and professionalism since she was pack of them all. She shouted at me and my husband (I already was crying due to horrendous pain) purely because we were speaking in English-the universal language. Her attitude was rude, body language was disgusting and I won’t ever come back to this place. And the orthopedic doctor only took 5 minutes to check my xray results. I wasn’t happy with the xray as it was requested insufficient. Only one angle was used with my both feet.',
    NULL, NULL, 'I twisted both my ankles, was terrified they would be broken. We were referred from Budva Health Center, the lady at the reception was AWFUL. She wasn’t wearing a name badge but it happened 06/10/26 night shift (about 10-11 pm). I want her to be warned quite firmly about respect, communication and professionalism since she was pack of them all. She shouted at me and my husband (I already was crying due to horrendous pain) purely because we were speaking in English-the universal language. Her attitude was rude, body language was disgusting and I won’t ever come back to this place. And the orthopedic doctor only took 5 minutes to check my xray results. I wasn’t happy with the xray as it was requested insufficient. Only one angle was used with my both feet.', NULL, NULL, NULL,
    0, '2026-10-15 00:00:00'),

(@user_andjela_vuckovic, @clinic_id, NULL, 'google_maps',
    'places/ChIJM8Gt42Q2TBMRvLuBwVtNCEQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT21Gck56bFlWbU52TjBwYVlrcHlURVZIVkV3eE4yYxAB',
    5, 'bs', 'Sve pohvale za odeljenje neurologije! Svi su toliko divni i posvećeni iako nema dovoljno kadra.',
    'Sve pohvale za odeljenje neurologije! Svi su toliko divni i posvećeni iako nema dovoljno kadra.', NULL, NULL, NULL, NULL, NULL,
    0, '2026-10-15 00:00:00'),

(@user_omer_isik, @clinic_id, NULL, 'google_maps',
    'places/ChIJM8Gt42Q2TBMRvLuBwVtNCEQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xkMWRqWTBURWsyZWtZM2JVSjFkVmh5V2s5blZsRRAB',
    1, 'en', 'Terrible place. Terrible horrendous reception. Lady did nothing but shout at us. Absolutely terrifying experience. I have never seen people being shout at for not knowing the local language. At one point I thought she was being racist. Would prefer going back with broken leg without any treatment than coming here. The worst.',
    NULL, NULL, 'Terrible place. Terrible horrendous reception. Lady did nothing but shout at us. Absolutely terrifying experience. I have never seen people being shout at for not knowing the local language. At one point I thought she was being racist. Would prefer going back with broken leg without any treatment than coming here. The worst.', NULL, NULL, NULL,
    0, '2026-10-08 00:00:00'),

(@user_mehmet_kursad_suata, @clinic_id, NULL, 'google_maps',
    'places/ChIJM8Gt42Q2TBMRvLuBwVtNCEQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2tKMVVsWk5VemM0Y1VzeVgxUTRkV1UyZEZvMFpWRRAB',
    1, 'en', 'Disgusting people at the reception. Our friend got injured at the Central Budva. We went to nearby hospital at the Budva central. Lovely bunch helped us and referred us to this hospital before midnight. Even arranged us a cab.
After that we arrived at this hospital, there were a lady and a man at the reception and lady was nothing short of a pure evil. She was shouting at us as if we had cursed her family for centuries. Incredibly rude, I cant even describe it how angry i got. If you have to go to this hospital, and I hope it never happens, try to talk with someone else or take someone local with you to the reception.',
    NULL, NULL, 'Disgusting people at the reception. Our friend got injured at the Central Budva. We went to nearby hospital at the Budva central. Lovely bunch helped us and referred us to this hospital before midnight. Even arranged us a cab.
After that we arrived at this hospital, there were a lady and a man at the reception and lady was nothing short of a pure evil. She was shouting at us as if we had cursed her family for centuries. Incredibly rude, I cant even describe it how angry i got. If you have to go to this hospital, and I hope it never happens, try to talk with someone else or take someone local with you to the reception.', NULL, NULL, NULL,
    0, '2026-10-08 00:00:00'),

(@user_dragan_segrt, @clinic_id, NULL, 'google_maps',
    'places/ChIJM8Gt42Q2TBMRvLuBwVtNCEQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2xJMlZHMUtUVTVQU0RWNk1Gb3hUMVJ4U1c0ME9GRRAB',
    5, 'ru', NULL,
    NULL, NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

(@user_du_ki, @clinic_id, NULL, 'google_maps',
    'places/ChIJM8Gt42Q2TBMRvLuBwVtNCEQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT210WVRGVkRhRzF6TjNKd2EydHhTVzVsYlhCcFdIYxAB',
    5, 'hr', 'Želim da izrazim iskrenu zahvalnost i veliko poštovanje prema cijelom timu bolnice Risan u kojoj se najmanje ulagalo a previše očekivalo-personal uvjek ljubazan i na usluzi kako pacijenta tako i članovima porodice  a to jr posebno doprinjeo  dr Popović Vlado, veliki čovjek i izuzetni neurohirurg.
Dr Popović je, prije svega, čovjek koji uliva povjerenje, sigurnost i nadu. Njegova stručnost, posvećenost pacijentu, smirenost i ljudskost ostavljaju snažan utisak. U trenucima kada je čovjeku najteže, mnogo znači imati ljekara koji pristupa pacijentu sa razumijevanjem, strpljenjem i iskrenom željom da pomogne kao i saradnja sa članovima porodice dotičnog pacijenta.
Kao neurohirurg, dr Popović je vrhunski stručnjak, ali ono što ga posebno izdvaja jeste njegova ljudskost i odnos prema pacijentima. Takvi ljekari vraćaju vjeru u medicinu i pokazuju koliko znanje, iskustvo i dobro srce mogu zajedno da znače.
Velike pohvale i zahvalnost upućujem i cijelom osoblju bolnice Risan na profesionalnosti, ljubaznosti i brizi o pacijentima. Od prvog do posljednjeg trenutka osjećao/la sam poštovanje i pažnju.
Od srca preporučujem bolnicu Risan i dr Popovića. Hvala vam na svemu što radite za svoje pacijente. Želim vam mnogo uspjeha i da još dugo budete oslonac i nada ljudima kojima je pomoć najpotrebnija.',
    'Želim da izrazim iskrenu zahvalnost i veliko poštovanje prema cijelom timu bolnice Risan u kojoj se najmanje ulagalo a previše očekivalo-personal uvjek ljubazan i na usluzi kako pacijenta tako i članovima porodice  a to jr posebno doprinjeo  dr Popović Vlado, veliki čovjek i izuzetni neurohirurg.
Dr Popović je, prije svega, čovjek koji uliva povjerenje, sigurnost i nadu. Njegova stručnost, posvećenost pacijentu, smirenost i ljudskost ostavljaju snažan utisak. U trenucima kada je čovjeku najteže, mnogo znači imati ljekara koji pristupa pacijentu sa razumijevanjem, strpljenjem i iskrenom željom da pomogne kao i saradnja sa članovima porodice dotičnog pacijenta.
Kao neurohirurg, dr Popović je vrhunski stručnjak, ali ono što ga posebno izdvaja jeste njegova ljudskost i odnos prema pacijentima. Takvi ljekari vraćaju vjeru u medicinu i pokazuju koliko znanje, iskustvo i dobro srce mogu zajedno da znače.
Velike pohvale i zahvalnost upućujem i cijelom osoblju bolnice Risan na profesionalnosti, ljubaznosti i brizi o pacijentima. Od prvog do posljednjeg trenutka osjećao/la sam poštovanje i pažnju.
Od srca preporučujem bolnicu Risan i dr Popovića. Hvala vam na svemu što radite za svoje pacijente. Želim vam mnogo uspjeha i da još dugo budete oslonac i nada ljudima kojima je pomoć najpotrebnija.', NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

(@user_alex_si, @clinic_id, NULL, 'google_maps',
    'places/ChIJM8Gt42Q2TBMRvLuBwVtNCEQ/reviews/Ci9DQUlRQUNvZENodHljRjlvT2poU05WOVBVMk5vZVhoWU16azRiRmxWTWpNMFZXYxAB',
    1, 'bs', 'Moja dvanaestogodišnja ćerka je povrijedila prst na nozi. Uradili smo rendgen u Budvi i uputili su nas u bolnicu u Risnu.

Stigli smo u Risan kod ortopeda u 13:00, sačekali svoj red i ušli kod doktora u 14:40. Doktor nije htio da nas primi, rekao je da je umoran i da dođemo sjutra, iako mu radno vrijeme traje do 15:00.

Na recepciji smo tražili da pozovu dežurnog doktora, ali su odbili i samo nam rekli: „Dođite sjutra.“',
    'Moja dvanaestogodišnja ćerka je povrijedila prst na nozi. Uradili smo rendgen u Budvi i uputili su nas u bolnicu u Risnu.

Stigli smo u Risan kod ortopeda u 13:00, sačekali svoj red i ušli kod doktora u 14:40. Doktor nije htio da nas primi, rekao je da je umoran i da dođemo sjutra, iako mu radno vrijeme traje do 15:00.

Na recepciji smo tražili da pozovu dežurnog doktora, ali su odbili i samo nam rekli: „Dođite sjutra.“', NULL, NULL, NULL, NULL, NULL,
    0, '2026-09-29 00:00:00'),

